#!/usr/bin/env Rscript
# Generates one Quarto page per site listed in sites.csv (runs as a Quarto pre-render step).
#
# Each page has:
#   1. an auto-generated "Site information" bullet list built from the CSV row
#      (empty cells are simply left out)
#   2. an optional "About this site" section made of
#        - site-content/images/<slug>.(jpg|jpeg|png|webp|gif|svg)   (optional image)
#        - site-content/<slug>.md                                    (optional free text)
#
# <slug> is the site name in lowercase ASCII with hyphens,
# e.g. "Example Site A" -> example-site-a
#
# Quarto runs pre-render scripts from the project root, so paths are relative to it.

source("r/utils.R")

out_dir     <- "sites"
content_dir <- "site-content"
img_dir     <- file.path(content_dir, "images")
img_ext     <- c("jpg", "jpeg", "png", "webp", "gif", "svg")
marker      <- "<!-- auto-generated by r/generate_sites.R - do not edit -->"

# Metadata fields shown on each site page, in this order.
# A field whose cell in sites.csv is empty is left out of the page.
info_fields <- c(
  coords        = "Coordinates",
  nb_control = "Control plots",
  nb_logged  = "Logged plots",
  plot_size  = "Plot size (ha)",
  years   = "Census period",
  nb_census   = "Number of censuses",
  year_logging   = "Logging year",
  dbh_min = "Minimum Diameter at Breast Height included (cm)",
  url = "Website"
)

# "Site information" section as a bullet list; no section at all if every field is empty
info_section <- function(r) {
  vals <- vapply(names(info_fields), function(k) {
    v <- r[[k]]
    if (is.null(v) || is.na(v)) "" else trimws(gsub("[\r\n]+", " ", v))
  }, character(1))
  keep <- vals != ""
  if (!any(keep)) return(character(0))
  c("## Site information {#site-information}", "",
    paste0("- **", info_fields[keep], ":** ", vals[keep]), "")
}

yaml_str <- function(x) paste0('"', gsub('"', '\\\\"', gsub("\\", "\\\\", x, fixed = TRUE)), '"')

sites <- read_sites("data/sites.csv")
# create columns in sites table
sites$years <- paste(sites$first_census, sites$last_census, sep = "-")
sites$coords <- paste(
  sapply(sites$lat, function(x) convert_coord(x, TRUE)), 
  sapply(sites$lon, function(x) convert_coord(x, FALSE)), sep = ", "
)

slugs <- slugify(sites$site)

dups <- unique(slugs[duplicated(slugs)])
if (length(dups)) {
  stop("Several sites give the same page name: ", paste(dups, collapse = ", "))
}

dir.create(out_dir, showWarnings = FALSE)

# remove stale generated pages
for (f in list.files(out_dir, pattern = "\\.qmd$", full.names = TRUE)) {
  if (any(grepl(marker, readLines(f, warn = FALSE, encoding = "UTF-8"), fixed = TRUE))) file.remove(f)
}

for (i in seq_len(nrow(sites))) {
  r    <- sites[i, ]
  slug <- slugs[i]
  
  lines <- c(
    "---",
    paste0("title: ", yaml_str(r$site)),
    "---",
    "",
    marker,
    "",
    "[\u2190 Back to the map](../map.html)",
    ""
  )
  lines <- c(lines, info_section(r))
  
  img_candidates <- file.path(img_dir, paste0(slug, ".", img_ext))
  image <- img_candidates[file.exists(img_candidates)][1]
  text  <- file.path(content_dir, paste0(slug, ".md"))
  
  if (!is.na(image) || file.exists(text)) {
    lines <- c(lines, "## About this site {#about}", "")
    if (!is.na(image)) {
      lines <- c(lines,
                 paste0("![](../site-content/images/", basename(image), "){fig-alt=", yaml_str(r$site), " .img-fluid}"),
                 "")
    }
    if (file.exists(text)) {
      lines <- c(lines, paste0("{{< include ../site-content/", basename(text), " >}}"), "")
    }
  }
  
  con <- file(file.path(out_dir, paste0(slug, ".qmd")), open = "wb")
  writeLines(enc2utf8(lines), con, useBytes = TRUE)
  close(con)
}

message("generate_sites: wrote ", nrow(sites), " site page(s) to ", out_dir, "/")